const AGENT_ID = '';
const AGENT_PHONE_NUMBER_ID = '';
const PROVIDER = 'twilio';
const ORG = '11111111-1111-1111-1111-111111111111';

const body = $input.first().json.body ?? $input.first().json;
const errors = [];
const agentId = String(body.agent_id || AGENT_ID).trim();
const phoneNumberId = String(body.agent_phone_number_id || AGENT_PHONE_NUMBER_ID).trim();
const provider = String(body.provider || PROVIDER).trim();
const patientName = String(body.patient_name || '').trim();
const reason = String(body.reason || '').trim();
const phoneRaw = String(body.phone || body.to_number || '').trim();
const digits = phoneRaw.replace(/[^0-9]/g, '');
const phone = `+${digits}`;

if (!agentId) errors.push('Set AGENT_ID in Prepare Outbound Call, or send agent_id.');
if (!phoneNumberId) errors.push('Set AGENT_PHONE_NUMBER_ID in Prepare Outbound Call, or send agent_phone_number_id.');
if (/^\+?\d{7,}$/.test(phoneNumberId)) errors.push('AGENT_PHONE_NUMBER_ID must be the ElevenLabs phone number id (it starts with phnum_), not the +1 phone number.');
if (!['twilio', 'sip_trunk'].includes(provider)) errors.push('provider must be twilio or sip_trunk.');
if (!patientName) errors.push('patient_name is required.');
if (!reason) errors.push('reason is required.');
if (digits.length < 7) errors.push('phone must include at least 7 digits.');

const urls = {
  twilio: 'https://api.elevenlabs.io/v1/convai/twilio/outbound-call',
  sip_trunk: 'https://api.elevenlabs.io/v1/convai/sip-trunk/outbound-call'
};

return [{
  json: {
    _valid: errors.length === 0,
    _errors: errors,
    elevenlabs_url: urls[provider] || urls.twilio,
    agent_id: agentId,
    agent_phone_number_id: phoneNumberId,
    to_number: phone,
    phone_last10: digits.slice(-10),
    organization_id: String(body.organization_id || ORG).trim(),
    patient_name: patientName,
    reason
  }
}];

const body = $json.body ?? [];
const matches = Array.isArray(body) ? body : [];
const prior = $('Prepare Outbound Call').item.json;
const ids = matches.map((row) => row.id).filter(Boolean);
const named = matches.find((row) => `${row.first_name || ''} ${row.last_name || ''}`.trim().toLowerCase() === prior.patient_name.toLowerCase());
const chosen = named ?? matches[0] ?? null;
const patientName = chosen ? `${chosen.first_name || ''} ${chosen.last_name || ''}`.trim() || prior.patient_name : prior.patient_name;
return [{ json: { ...prior, patient_name: patientName, patient_ids: ids.join(','), patient_found: ids.length > 0 } }];

const SERVICE_LABELS = {
  general_cleaning: 'cleaning', emergency_dental: 'emergency visit', dental_exam: 'dental exam',
  implants: 'implant visit', invisalign: 'Invisalign visit', whitening: 'whitening', crowns: 'crown visit',
  root_canal: 'root canal', childrens_dentistry: "children's visit", other: 'appointment'
};
const GENERIC = new Set(['a follow-up to your recent call', 'a follow-up to your recent visit']);

function spokenWhen(iso) {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'America/Toronto', weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true }).formatToParts(new Date(iso));
  const get = (type) => parts.find((part) => part.type === type)?.value ?? '';
  const period = get('dayPeriod') === 'AM' ? 'a.m.' : 'p.m.';
  const clock = get('minute') === '00' ? `${get('hour')} ${period}` : `${get('hour')}:${get('minute')} ${period}`;
  return `${get('weekday')}, ${get('month')} ${get('day')} at ${clock}`;
}

const prior = $('Pick Patient').item.json;
let appointment = null;
try {
  const body = $('Get Upcoming Appointment').item.json.body ?? [];
  appointment = Array.isArray(body) ? body[0] ?? null : null;
} catch (e) {
  appointment = null;
}

let upcomingVisit = 'none';
let callReason = prior.reason;
if (appointment && appointment.starts_at) {
  const service = SERVICE_LABELS[appointment.service] || 'appointment';
  const dentist = appointment.dentist_name || 'the dentist';
  upcomingVisit = `${service} with ${dentist} on ${spokenWhen(appointment.starts_at)}`;
  if (GENERIC.has(String(callReason).trim().toLowerCase())) callReason = `your ${upcomingVisit}`;
}

const firstName = prior.patient_name.split(/\s+/)[0];
const openingLine = `Hi ${firstName}, this is Maple Grove Dental Clinic calling about ${callReason}. Do you have a moment?`;

return [{
  json: {
    elevenlabs_url: prior.elevenlabs_url,
    elevenlabs_body: {
      agent_id: prior.agent_id,
      agent_phone_number_id: prior.agent_phone_number_id,
      to_number: prior.to_number,
      conversation_initiation_client_data: {
        dynamic_variables: {
          organization_id: prior.organization_id,
          direction: 'outbound',
          patient_name: prior.patient_name,
          caller_name: prior.patient_name,
          call_reason: callReason,
          upcoming_visit: upcomingVisit,
          opening_line: openingLine
        }
      }
    }
  }
}];

function asText(value) {
  if (value == null || value === '') return '';
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(asText).filter(Boolean).join(' ');
  if (typeof value === 'object') return asText(value.message || value.msg || value.status || value.error || value.description) || JSON.stringify(value);
  return String(value);
}
let payload = $json.body !== undefined ? $json.body : $json;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) { payload = { message: payload }; }
}
if (payload && payload.body !== undefined && (payload.statusCode || payload.status)) {
  payload = payload.body;
  if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (e) { payload = { message: payload }; }
  }
}
const status = Number($json.statusCode || $json.status || 0);
const detail = asText(payload && payload.detail) || asText(payload && payload.error) || asText($json.error);
const upstream = asText(payload && payload.message);
const ok = status >= 200 && status < 300 && (!payload || payload.success !== false);
let failure = upstream || detail;
if (!failure || failure === '{}') failure = `ElevenLabs did not start the call (HTTP ${status}).`;
if (/first_message|override/i.test(failure)) failure += ' The greeting is the opening_line variable, so leave the first-message override off.';
if (/sip/i.test(failure)) failure += ' In Prepare Outbound Call, set PROVIDER to sip_trunk.';
return [{
  json: {
    success: ok,
    conversation_id: (payload && payload.conversation_id) || null,
    message: ok ? (upstream || 'Outbound call started.') : failure,
    status_code: 200
  }
}];
